// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MY_BANK c;
    Log log_;

    function setUp() public {
        log_ = new Log();
        c = new MY_BANK(address(log_));
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(amount > 0 && amount < type(uint256).max / 2);

        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok; try c.Put{value: amount}(uint256(0)) { ok = true; } catch { ok = false; }
        assertTrue(ok, "Put reverted");

        // The deposit must have been recorded: History[0] exists and matches the call.
        (address sender, string memory data, uint256 val, ) = log_.History(0);
        assertTrue(
            sender == actor &&
            val == amount &&
            keccak256(bytes(data)) == keccak256(bytes("Put")),
            "deposit not recorded correctly in log"
        );
    }
}
